#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    int x = *(const int*)a;
    int y = *(const int*)b;
    return (x > y) - (x < y);
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;
    int *A = (int*)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
    }
    qsort(A, N, sizeof(int), cmp);
    long long ans = 0;
    for (int k = 2; k < N; k++) {
        int target = A[k];
        int l = 0, r = k - 1;
        while (l < r) {
            if ((long long)A[l] + A[r] > target) {
                ans += (r - l);
                r--;
            } else {
                l++;
            }
        }
    }
    printf("%lld\n", ans);
    free(A);
    return 0;
}
